from pathlib import Path

p = Path('src/components/InstructorAccountControls.tsx')
s = p.read_text()
s = s.replace("import { InstructorAccountControls", "import { InstructorAccountControls") if False else s
if "import { DynamicScenarioBuilder } from './DynamicScenarioBuilder'" not in s:
    s = s.replace("import { APP_VERSION } from '../appVersion'\n", "import { APP_VERSION } from '../appVersion'\nimport { DynamicScenarioBuilder } from './DynamicScenarioBuilder'\n")
s = s.replace("  onLoadScenario: (scenario: InstructorScenarioSnapshot) => void\n}", "  onLoadScenario: (scenario: InstructorScenarioSnapshot) => void\n  simulationPaused: boolean\n  onSimulationPausedChange: (paused: boolean) => void\n}")
s = s.replace("export function InstructorAccountControls({ role, currentScenario, onLoadScenario }: InstructorAccountControlsProps)", "export function InstructorAccountControls({ role, currentScenario, onLoadScenario, simulationPaused, onSimulationPausedChange }: InstructorAccountControlsProps)")
old = '''            {account ? (\n              <>\n                <section className="scenario-create-card">'''
new = '''            {scenarioType === 'dynamic' && account ? (\n              <DynamicScenarioBuilder\n                currentScenario={currentScenario}\n                dynamicPresets={dynamicPresets}\n                staticPresets={staticPresets}\n                simulationPaused={simulationPaused}\n                onSimulationPausedChange={onSimulationPausedChange}\n                onRefresh={() => refreshPresets(account)}\n                onClose={() => setScenarioOpen(false)}\n              />\n            ) : account ? (\n              <>\n                <section className="scenario-create-card">'''
if old not in s:
    raise SystemExit('scenario manager insertion point not found')
s = s.replace(old, new, 1)
p.write_text(s)

p = Path('src/App.tsx')
s = p.read_text()
old = '''          <InstructorAccountControls\n            role={teachingSession.role}\n            currentScenario={currentInstructorScenario}\n            onLoadScenario={loadInstructorScenario}\n          />'''
new = '''          <InstructorAccountControls\n            role={teachingSession.role}\n            currentScenario={currentInstructorScenario}\n            onLoadScenario={loadInstructorScenario}\n            simulationPaused={simulationPaused}\n            onSimulationPausedChange={setSimulationPaused}\n          />'''
if old not in s:
    raise SystemExit('App InstructorAccountControls block not found')
s = s.replace(old, new, 1)
p.write_text(s)

p = Path('src/account.css')
s = p.read_text()
s += r'''\n\n/* v0.82 dynamic scenario file-manager builder */\n.scenario-manager-dialog:has(.dynamic-file-manager) { width: min(1180px, calc(100vw - 28px)); max-height: min(880px, calc(100vh - 28px)); }\n.dynamic-file-manager { display:grid; grid-template-columns:240px minmax(0,1fr); min-height:620px; border:1px solid #30434d; background:#091216; }\n.dynamic-scenario-sidebar { border-right:1px solid #30434d; background:#0b151a; min-width:0; }\n.dynamic-sidebar-heading { display:flex; align-items:center; justify-content:space-between; padding:12px 13px; border-bottom:1px solid #263840; }\n.dynamic-sidebar-heading span { color:#8da2ab; font-size:10px; text-transform:uppercase; letter-spacing:.09em; }\n.dynamic-sidebar-heading strong { color:#dbe8ed; font-size:11px; }\n.dynamic-scenario-list { display:grid; }\n.dynamic-scenario-list button { border:0; border-bottom:1px solid #22333b; border-radius:0; background:transparent; text-align:left; padding:11px 13px; min-height:54px; }\n.dynamic-scenario-list button:hover:not(:disabled) { background:#122028; }\n.dynamic-scenario-list button.selected { background:#183026; box-shadow:inset 3px 0 #68b97b; }\n.dynamic-scenario-list strong,.dynamic-scenario-list small { display:block; }\n.dynamic-scenario-list strong { color:#dce8ec; font-size:11px; }\n.dynamic-scenario-list small { margin-top:3px; color:#71858e; font-size:9px; }\n.dynamic-add-scenario strong { color:#8ed6a1; }\n.dynamic-builder-pane { min-width:0; padding:15px; overflow:auto; max-height:720px; }\n.dynamic-scenario-header-block { display:grid; grid-template-columns:minmax(220px,.75fr) minmax(300px,1.25fr); gap:11px; padding:14px; border:1px solid #334853; background:#0d191f; }\n.dynamic-scenario-header-block label { display:grid; gap:6px; }\n.dynamic-scenario-header-block label > span,.dynamic-stage-source-row > span { color:#93a7af; font-size:10px; }\n.dynamic-scenario-header-block input,.dynamic-scenario-header-block textarea,.dynamic-stage-title-row input,.dynamic-stage-source-row select,.dynamic-setting-value { width:100%; border:1px solid #3a4f5a; border-radius:0; background:#081116; color:#edf5f7; padding:8px 9px; font:inherit; outline:none; }\n.dynamic-scenario-header-block textarea { resize:vertical; min-height:68px; }\n.dynamic-stage-stack { margin-top:12px; }\n.dynamic-stage-shell { display:grid; justify-items:center; }\n.dynamic-stage-card { width:100%; border:1px solid #3b505b; background:#0a1419; }\n.dynamic-stage-title-row { display:flex; align-items:center; justify-content:space-between; gap:10px; padding:11px 12px; border-bottom:1px solid #2c4049; background:#101e24; }\n.dynamic-stage-title-row > div { display:grid; grid-template-columns:auto minmax(180px,1fr); align-items:center; gap:10px; flex:1; }\n.dynamic-stage-title-row span { color:#7ec6dc; font-size:10px; font-weight:800; text-transform:uppercase; letter-spacing:.08em; }\n.dynamic-stage-title-row input { min-height:34px; }\n.dynamic-stage-remove { width:32px; height:32px; padding:0; border-radius:0; color:#e5aaaa; border-color:#6b4040; background:#231515; }\n.dynamic-stage-source-row { display:grid; grid-template-columns:90px minmax(0,1fr); align-items:center; gap:9px; padding:10px 12px; border-bottom:1px solid #263942; }\n.dynamic-stage-sections { display:grid; gap:1px; background:#22343d; }\n.dynamic-stage-sections details { background:#0b151a; }\n.dynamic-stage-sections summary { cursor:pointer; padding:10px 12px; color:#dce7eb; font-size:10px; font-weight:800; letter-spacing:.08em; }\n.dynamic-stage-sections summary small { margin-left:8px; color:#718790; font-weight:600; }\n.dynamic-setting-grid { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:1px; background:#21343c; border-top:1px solid #21343c; }\n.dynamic-setting-row { display:grid; grid-template-columns:minmax(0,1fr) 120px; align-items:center; gap:8px; min-height:45px; padding:6px 9px; background:#0a1419; }\n.dynamic-setting-row.disabled { opacity:.48; }\n.dynamic-setting-enable { display:flex; align-items:center; gap:7px; min-width:0; color:#b6c6cc; font-size:10px; }\n.dynamic-setting-enable input { flex:0 0 auto; }\n.dynamic-setting-value { min-height:32px; padding:5px 7px; font-size:10px; }\n.dynamic-setting-value.boolean { width:18px; min-height:18px; justify-self:end; }\n.dynamic-add-stage { width:38px; height:38px; margin:7px 0; padding:0; border-radius:0; color:#a6ddb3; border-color:#477759; background:#102319; font-size:20px; line-height:1; }\n.dynamic-builder-footer { position:sticky; bottom:-15px; display:grid; grid-template-columns:auto auto 1fr auto auto; gap:8px; padding:12px 0 0; margin-top:5px; background:linear-gradient(180deg,rgba(9,18,22,0),#091216 18px); }\n.dynamic-builder-footer button { border-radius:0; }\n@media (max-width:900px) { .dynamic-file-manager { grid-template-columns:180px minmax(0,1fr); } .dynamic-setting-grid { grid-template-columns:1fr; } .dynamic-scenario-header-block { grid-template-columns:1fr; } }\n@media (max-width:650px) { .dynamic-file-manager { grid-template-columns:1fr; } .dynamic-scenario-sidebar { border-right:0; border-bottom:1px solid #30434d; } .dynamic-scenario-list { grid-template-columns:repeat(2,minmax(0,1fr)); } .dynamic-builder-footer { grid-template-columns:1fr 1fr; } .dynamic-builder-footer span { display:none; } }\n'''
p.write_text(s)
